struct TrieNode {
    TrieNode* children[26] = {nullptr};
    int best_idx = -1;
};

class Solution {
public:
    vector<int> stringIndices(vector<string>& wordsContainer, vector<string>& wordsQuery) {
        TrieNode* root = new TrieNode();

        auto isBetter = [&](int new_idx, int old_idx) {
            if (old_idx == -1) return true;
            int lenNew = wordsContainer[new_idx].size();
            int lenOld = wordsContainer[old_idx].size();
            if (lenNew != lenOld) return lenNew < lenOld;
            return new_idx < old_idx;
        };

        for (int i = 0; i < wordsContainer.size(); ++i) {
            if (isBetter(i, root->best_idx)) root->best_idx = i;
            TrieNode* curr = root;
            string& w = wordsContainer[i];
            for (int j = (int)w.size() - 1; j >= 0; --j) {
                int c = w[j] - 'a';
                if (!curr->children[c]) curr->children[c] = new TrieNode();
                curr = curr->children[c];
                if (isBetter(i, curr->best_idx)) curr->best_idx = i;
            }
        }

        vector<int> ans;
        for (const string& q : wordsQuery) {
            TrieNode* curr = root;
            for (int j = (int)q.size() - 1; j >= 0; --j) {
                int c = q[j] - 'a';
                if (!curr->children[c]) break;
                curr = curr->children[c];
            }
            ans.push_back(curr->best_idx);
        }
        return ans;
    }
};

class Solution {
    static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        int bestIdx = -1;
    }

    public int[] stringIndices(String[] wordsContainer, String[] wordsQuery) {
        TrieNode root = new TrieNode();

        for (int i = 0; i < wordsContainer.length; i++) {
            if (isBetter(wordsContainer, i, root.bestIdx)) {
                root.bestIdx = i;
            }
            TrieNode curr = root;
            String w = wordsContainer[i];
            for (int j = w.length() - 1; j >= 0; j--) {
                int c = w.charAt(j) - 'a';
                if (curr.children[c] == null) {
                    curr.children[c] = new TrieNode();
                }
                curr = curr.children[c];
                if (isBetter(wordsContainer, i, curr.bestIdx)) {
                    curr.bestIdx = i;
                }
            }
        }

        int[] ans = new int[wordsQuery.length];
        for (int i = 0; i < wordsQuery.length; i++) {
            TrieNode curr = root;
            String q = wordsQuery[i];
            for (int j = q.length() - 1; j >= 0; j--) {
                int c = q.charAt(j) - 'a';
                if (curr.children[c] == null) break;
                curr = curr.children[c];
            }
            ans[i] = curr.bestIdx;
        }
        return ans;
    }

    private boolean isBetter(String[] words, int newIdx, int oldIdx) {
        if (oldIdx == -1) return true;
        if (words[newIdx].length() != words[oldIdx].length()) {
            return words[newIdx].length() < words[oldIdx].length();
        }
        return newIdx < oldIdx;
    }
}

